<h1>Submissions</h1>
<?php if ($newCount > 0): ?><div class="alert a-info"><strong><?= (int)$newCount ?></strong> new since your last visit (highlighted).</div><?php endif; ?>
<form class="card filters" method="get" action="<?= e(url('/admin/submissions')) ?>">
  <input name="q" type="search" placeholder="Participant name or email" value="<?= e(get('q')) ?>">
  <select name="quiz"><option value="">All quizzes</option><?php foreach ($quizzes as $z): ?><option value="<?= (int)$z['id'] ?>" <?= (int)get('quiz') === (int)$z['id'] ? 'selected' : '' ?>><?= e($z['title']) ?></option><?php endforeach; ?></select>
  <select name="elig"><option value="">Any eligibility</option><?php foreach (ELIG_LABELS as $k => $l): ?><option value="<?= $k ?>" <?= get('elig') === $k ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select>
  <select name="status"><option value="">Any status</option><?php foreach (['submitted', 'timed_out', 'abandoned'] as $s): ?><option <?= get('status') === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select>
  <label>From <input type="date" name="from" value="<?= e(get('from')) ?>"></label><label>To <input type="date" name="to" value="<?= e(get('to')) ?>"></label>
  <button class="btn btn-sm" type="submit">Filter</button><a class="btn btn-sm btn-outline" href="<?= e(url('/admin/submissions/export') . qs(['page' => null])) ?>">Export CSV</a></form>
<div class="table-wrap"><table class="cards-sm"><thead><tr><th>#</th><th>Participant</th><th>Quiz</th><th>Score</th><th>Time</th><th>Left page</th><th>Eligibility</th><th>Submitted</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr class="<?= (int)$r['id'] > $seenBefore ? 'fresh' : '' ?>"><td data-l="#"><?= (int)$r['id'] ?></td><td data-l="Participant"><span class="person"><?= avatar_html(['id' => $r['user_id'], 'full_name' => $r['full_name'], 'has_avatar' => $r['has_avatar']], 34) ?><span><?= e($r['full_name']) ?><small><?= e($r['email']) ?></small></span></span></td><td data-l="Quiz"><?= e($r['title']) ?> <small>(attempt <?= (int)$r['attempt_no'] ?>)</small></td>
<td data-l="Score"><?= e(num($r['final_marks'])) ?>/<?= (int)$r['max_marks'] ?> (<?= e(num($r['percentage'])) ?>%)</td><td data-l="Time"><?= e(fmt_duration($r['duration_seconds'] === null ? null : (int)$r['duration_seconds'])) ?></td><td data-l="Left page"><?= (int)$r['lefts'] ?></td><td data-l="Eligibility"><?= badge($r['eligibility']) ?></td><td data-l="Submitted"><?= e(fmt_dt($r['submitted_at'])) ?></td><td><a href="<?= e(url('/admin/submissions/' . $r['id'])) ?>">Inspect</a></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="9" class="empty">No submissions match.</td></tr><?php endif; ?></tbody></table></div><?= pager($pg, '/admin/submissions') ?>
